-- 0130 — چهار بستهٔ چندجلسه‌ای سیستمی «طرح درمان» برای پایهٔ اول تا سوم (۷ تا ۹ سال — خواست کارفرما)
-- خواست کارفرما: «از ترکیب کارت‌های آماده… بسته‌ها مثلاً حافظه برای چند جلسه باشن بهتره» — هر قالبِ این فایل
--   یک بستهٔ چندجلسه‌ای است (جلسهٔ ۱ تا جلسهٔ ۵/۶ با ترتیب مشخص، ~۳۰ تا ۴۰ دقیقه) که با ترکیب کارت‌های واقعی
--   بانک تمرین ساخته شده، نه فهرست تک‌موردی.
-- محتوای هر قالب «اکیداً» از دارایی‌های authored موجود ساخته شده است (قانون 0128 عیناً تکرار می‌شود):
--   · کلید هدف: فقط کلیدهای src/domain/clinical-engine/targets.ts (۲۲ هدف) — حافظهٔ کاری کلید اختصاصی
--     خودش را دارد (working_memory) و بدون نیاز به کلید جانشین مستقیماً استفاده شده است.
--   · کلید پراپ: فقط ce-probe-write-v1 / ce-probe-calc-v1 (پراپ‌های واقعی موتور 0076). برای حافظهٔ کاری و
--     توجه هیچ پراپی در موتور نیست — پایش با بازاجراهای رفتاری/فرم‌های باتری انجام و این شکاف صراحتاً ثبت است.
--   · ابزار ارجاعی: فقط کلیدهای موجود باتری (battery-*.json): SNAP-IV والد/معلم، SDQ معلم، فرم‌های SLD نوشتن/حساب.
--   · کارت‌ها: کارت‌های authored بانک (seed 0043 + 0129) با linkId لینک شده‌اند؛ کارت‌های نگه‌داشتهٔ بانک تولید
--     («حافظهٔ فعال» کانونی ادغامی، شمارش برعکس، بازی حافظهٔ شنیداری، بازی حافظهٔ اشکال، فراستیگ، ماز،
--     پروتکل پیش‌نیاز نوشتن، پروتکل پیش‌نیازهای مهارت ریاضی بخش ۱، سری توجه/تمرکز، توجه انتخابی/انتقالی،
--     دقت و توجه پایدار، بازی دقت و پردازش، تمیز دیداری، هماهنگی دو نیمکره، حافظهٔ دیداری) در متن آیتم با
--     عنوانِ رسمیِ ردیفِ نگه‌داشته صدا زده شده‌اند — شناسهٔ پایدار این ردیف‌ها در خروجی بانک ثبت نیست، پس
--     linkId ساختگی برایشان نوشته نشد (لینک هوایی/شناسهٔ ساختگی = نقض قانون کلیدهای موجود). فقط کارت‌های
--     با رای نگه‌دار سند تکلیف استفاده شده‌اند؛ «پروتکل ریاضی ۲» شرطی است و ارجاع نگرفت.
--   · آیتم family فقط بدون فرم یا با فرم‌های family_fillable موجود (SNAP-IV/SDQ/SLD — همه در باتری).
-- الگوی D7: فقط-افزودنی، بدون CHECK، بدون trigger، idempotent با INSERT OR IGNORE و id/key ثابت لفظی.
-- فیلدها مطابق سرویس: protocol از ['learning','slow_learner','mental_ot','rehab']؛ steps JSON
--   ({key,title,hint?})؛ sessions_json JSON ({title,plan,criterion,items:[{type,text,done:false,linkId}]})؛
--   نوع آیتم‌ها از PATHWAY_ITEM_TYPES ('exercise','homework','game','instruction','event','probe','family').

-- ─── قالب 1 — بستهٔ حافظهٔ کاری پایهٔ اول تا سوم (اولویت ۱ کارفرما — ترکیب کارت‌های حافظه در ۶ جلسه) ───
INSERT OR IGNORE INTO pathway_templates (id, key, title, description, protocol, target_key, steps, sessions_json, is_system, active, created_by) VALUES (
  'dddddddd-8200-4000-8000-000000000008',
  'sys-wm-primary',
  'بستهٔ حافظهٔ کاری پایهٔ اول تا سوم — بستهٔ چندجلسه‌ای',
  'قالب سیستمی حافظهٔ کاری برای پایهٔ اول تا سوم (۷ تا ۹ سال) به‌شکل بستهٔ شش‌جلسه‌ای با ترتیب مشخص: خط پایهٔ بازی‌وار، پلهٔ دیداری، پلهٔ شنیداری، کارت کانونی حافظهٔ فعال، ترکیب و پردازش هم‌زمان، و بازسنجی رفتاری — با برنامهٔ تکرار روزانهٔ کوتاه بین جلسات. حافظهٔ کاری کلید اختصاصی خودش را در موتور دارد (working_memory) اما نه پراپ دارد و نه فرم باتری؛ پایش همین بسته با بازاجرای همان دو سنجهٔ جلسهٔ اول و برگ پیام خانواده انجام می‌شود و این شکاف صراحتاً ثبت است، نه با ابزار ساختگی پر شدن. جایگزین ارزیابی تخصصی (وکسلر/WMI) نیست.',
  'mental_ot',
  'working_memory',
  '[{"key":"baseline","title":"خط پایهٔ بازی‌وار","hint":"دو سنجهٔ ساده در جلسهٔ اول: طول دنبالهٔ معکوس و تعداد دستور دومرحله‌ای موفق؛ همین دو سنجه در جلسهٔ پایانی تکرار می‌شود."},{"key":"visual","title":"پلهٔ حافظهٔ دیداری","hint":"بازی حافظهٔ اشکال و سری کاربرگ حافظهٔ دیداری بانک تمرین؛ بار با موفقیت پله می‌گیرد، نه با فشار."},{"key":"auditory","title":"پلهٔ حافظهٔ شنیداری و دستور","hint":"بازی حافظهٔ شنیداری و دنبالهٔ دستور پلکانی؛ از یک مرحله شروع کنید و هر بار یک پله."},{"key":"combine","title":"کارت کانونی و پردازش هم‌زمان","hint":"حافظهٔ فعال کانونی بانک (پانزده فایل پس از ادغام) + تصویرسازی حین شنیدن و شکار صدا در نویز."},{"key":"monitor","title":"بازسنجی رفتاری و تثبیت","hint":"پراپ و فرم باتری برای این هدف موجود نیست؛ روند فقط با بازاجرای همان سنجه‌های جلسهٔ ۱ سنجیده می‌شود."}]',
  '[{"title":"جلسهٔ ۱ — خط پایهٔ بازی‌وار (۳۰ تا ۴۰ دقیقه)","plan":"اجرای دو سنجهٔ خط پایه و بستن قرارداد تکرار: روزی پنج دقیقه، سه روز در هفته؛ بار با موفقیت پله می‌گیرد.","criterion":"ثبت طول دنبالهٔ معکوس و تعداد دستور دومرحله‌ای موفق به‌عنوان مبنا.","items":[{"type":"game","text":"دستور دومرحله‌ایِ بازی‌وار — خط پایه: سه دستور دومرحله‌ای بدهید و موفق‌ها را بشمارید؛ نسخهٔ سخت با فاصلهٔ مزاحم در جلسهٔ ۴ می‌آید.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000211"},{"type":"exercise","text":"کارت بانک تمرین «شمارش برعکس» — سطح ۱: معکوس‌گویی از سه عدد؛ طول دنبالهٔ درست ثبت شود.","done":false,"linkId":null},{"type":"instruction","text":"قرارداد تکرار خانه: روزی پنج دقیقه، سه روز در هفته؛ جدول «توانستم» برای دیدن روند.","done":false,"linkId":null}]},{"title":"جلسهٔ ۲ — پلهٔ حافظهٔ دیداری","plan":"بازی حافظه و کاربرگ دیداری با بار صعودی؛ تکرار شمارش برعکس ادامه دارد.","criterion":"جفت‌زنی کامل در سطح شروع (چهار جفت) بدون راهنمای میان‌راه.","items":[{"type":"game","text":"کارت بانک تمرین «بازی حافظهٔ اشکال» — از چهار جفت شروع کنید و با هر موفقیت یک جفت اضافه کنید.","done":false,"linkId":null},{"type":"exercise","text":"کارت بانک تمرین «حافظهٔ دیداری — سری کاربرگ‌ها» (پس از ادغام سه کارت هم‌موضوع) — ده دقیقه.","done":false,"linkId":null},{"type":"homework","text":"تکرار شمارش برعکس سطح ۱؛ در موفقیت دو روز پیاپی به چهار عدد پله کنید.","done":false,"linkId":null}]},{"title":"جلسهٔ ۳ — پلهٔ حافظهٔ شنیداری و دنبالهٔ دستور","plan":"دنبالهٔ شنیداری و دنبالهٔ دستور از یک مرحله به سه مرحلهٔ بازی‌وار.","criterion":"اجرای دنبالهٔ دو مرحله‌ای بدون تکرار دستور.","items":[{"type":"game","text":"کارت بانک تمرین «بازی حافظهٔ شنیداری» — دنبالهٔ شنیداری را نگه دارد و به همان ترتیب برگرداند.","done":false,"linkId":null},{"type":"exercise","text":"دنبالهٔ دستور پلکانی (حافظهٔ کاری) — از یک مرحله شروع کنید و هر بار یک پله اضافه کنید.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000131"},{"type":"homework","text":"تکرار هفتهٔ خانه: بازی حافظهٔ شنیداری دو بار در هفته + شمارش برعکس روزانه.","done":false,"linkId":null}]},{"title":"جلسهٔ ۴ — کارت کانونی حافظهٔ فعال","plan":"کارت کانونی موج «حافظهٔ فعال» بانک تمرین (پانزده فایل پس از ادغام) در سطح متوسط + نسخهٔ سخت دستور دومرحله‌ای.","criterion":"اتمام سطح جلسهٔ کارت کانونی با خطای کم و بدون خستگی زودهنگام.","items":[{"type":"exercise","text":"کارت کانونی «حافظهٔ فعال» بانک تمرین — بخش جلسهٔ امروز ده تا دوازده دقیقه؛ خستگی علامت توقف است.","done":false,"linkId":null},{"type":"game","text":"دستور دومرحله‌ایِ بازی‌وار — نسخهٔ سخت: گام اول، دو دقیقه بازی مزاحم، گام دوم.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000211"},{"type":"homework","text":"شمارش برعکس سطح چهار تا پنج عدد؛ موفقیت در جدول «توانستم» ثبت شود.","done":false,"linkId":null}]},{"title":"جلسهٔ ۵ — ترکیب و پردازش هم‌زمان","plan":"ترکیب نگه‌داشتن و پردازش: تصویرسازی حین شنیدن و پردازش دوکاناله در نویز.","criterion":"برگرداندن سه جزء قصهٔ شنیده و شکار صدای هدف در نویز سبک.","items":[{"type":"exercise","text":"تصویرسازی حین شنیدن (حافظهٔ کاری) — قصهٔ کوتاه بشنود، در ذهن تصویر کند و برگرداند.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000132"},{"type":"exercise","text":"شکارِ صدا در نویز (حافظهٔ کاری) — در سکوت شروع کنید و نویز را کم‌کم اضافه کنید.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000133"},{"type":"homework","text":"تکرار ترکیبی: یکی از کارت‌های جلسه‌های قبل با یک پله بار بالاتر.","done":false,"linkId":null}]},{"title":"جلسهٔ ۶ — بازسنجی رفتاری و تثبیت","plan":"بازاجرای همان دو سنجهٔ جلسهٔ ۱ و مقایسه؛ تصمیم تداوم یا خروج با برنامهٔ خانهٔ دو ماه بعد.","criterion":"بهبود یا پایداری در هر دو سنجه؛ برنامهٔ تکرار خانگی نوشته شود.","items":[{"type":"event","text":"بازسنجی رفتاری: همان شمارش برعکس و سه دستور دومرحله‌ای جلسهٔ ۱ — نتیجه کنار مبنا ثبت شود.","done":false,"linkId":null},{"type":"family","text":"دفترچهٔ پیام مرکز-خانه: روند هفته در دو خط — کدام پله رفت، کدام پله گیر کرد.","done":false,"linkId":null},{"type":"instruction","text":"در نبود پراپ و فرم باتری برای حافظهٔ کاری، روند فقط با همین بازاجراهای رفتاری سنجیده می‌شود؛ ابزار ساختگی وارد نشود.","done":false,"linkId":null}]}]',
  1,
  1,
  'seed-m130'
);

-- ─── قالب 2 — نوشتن و املای پایهٔ اول و دوم (فراستیگ/ماز + پروتکل نوشتن در ۵ جلسه) ───
INSERT OR IGNORE INTO pathway_templates (id, key, title, description, protocol, target_key, steps, sessions_json, is_system, active, created_by) VALUES (
  'dddddddd-8200-4000-8000-000000000009',
  'sys-writing-g12',
  'نوشتن و املای پایهٔ اول و دوم — بستهٔ چندجلسه‌ای',
  'قالب سیستمی نوشتن و املاء برای پایهٔ اول و دوم (۷ تا ۹ سال): پنج جلسهٔ پیاپی از ادراک دیداری حرف (فراستیگ و ماز بانک تمرین) تا الگوی حرکتی، خط‌کشی و دیکتهٔ هدفمند، با پروب نوشتن به‌عنوان مبنا و پیگیری دو هفته‌ای خانواده. با قالب نارسانویسی متمایز است: تمرکز روی ساختن پایه‌های نوشتن در سن مدرسه، نه برچسب تشخیص؛ در شک حرکت ظریف مسیر کاردرمانی بازبینی شود و در شک ماندگار به قالب نارسانویسی برگردید.',
  'learning',
  'dysgraphia',
  '[{"key":"probe","title":"خط پایهٔ پروب نوشتن","hint":"ce-probe-write-v1 — خطای دیکته و روانی مبنا؛ نمونهٔ تاریخ‌دار ساخته شود."},{"key":"visual","title":"ادراک دیداری حرف","hint":"فراستیگ و ماز بانک تمرین + حرف‌های آینه‌ای؛ تفکیک دیداری پیش از مداد."},{"key":"motor","title":"الگوی حرکتی و خط","hint":"پروتکل پیش‌نیاز نوشتن بانک تمرین + نوشتن در هوا/ماسه و سه‌گانهٔ خط‌کشی."},{"key":"dictation","title":"املا و دیکتهٔ هدفمند","hint":"اول بگو، بعد بنویس؛ کیفیت سه سطر، نه حجم یک صفحه."},{"key":"monitor","title":"پروب پیگیری و خانواده","hint":"پروب هر دو جلسه؛ فرم خانوادهٔ نوشتن برای پیگیری دو هفته‌ای خانه."}]',
  '[{"title":"جلسهٔ ۱ — پروب پایه و شرح‌حال نوشتن (۳۰ تا ۴۰ دقیقه)","plan":"اجرای پروب مبنا و ساختن نمونهٔ تاریخ‌دار؛ مرور نتیجهٔ چک‌لیست نوشتن و هم‌رأیی خانه.","criterion":"ثبت خطای دیکته و روانی مبنا در پروب مسیر.","items":[{"type":"probe","text":"اجرای ce-probe-write-v1 — ثبت خطای دیکتهٔ خطادار و روانی نوشتن به‌عنوان مبنا.","done":false,"linkId":null},{"type":"event","text":"مرور نتیجهٔ ce-sld-wri-v1 (فرم خانواده/معلم) و هم‌رأیی خانه بر دو هدف جلسات بعد.","done":false,"linkId":null}]},{"title":"جلسهٔ ۲ — ادراک دیداری حرف (فراستیگ و ماز)","plan":"تفکیک دیداری-فضایی پیش از مداد؛ حرف‌های هم‌شکل با نقطه‌شماری بلند.","criterion":"هفت تفکیک درست از ده در برگ حرف‌های هم‌شکل.","items":[{"type":"exercise","text":"کارت بانک تمرین «فراستیگ — کاربرگ‌های درک دیداری-فضایی» — یک برگ در جلسه، ده دقیقه.","done":false,"linkId":null},{"type":"exercise","text":"کارت بانک تمرین «ماز — کاربرگ‌های درک دیداری-فضایی و حرکت چشم» — پنج تا هفت دقیقه به‌عنوان گرم‌کردن.","done":false,"linkId":null},{"type":"exercise","text":"تمرین حرف‌های آینه‌ای ب/ت/ث/ن/ی — نقطه‌شماری بلند، کپی کنار الگو و سپس از حافظه.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000203"},{"type":"homework","text":"دو برگ فراستیگ در خانه در هفته؛ هر برگ بیشتر از ده دقیقه نکشد.","done":false,"linkId":null}]},{"title":"جلسهٔ ۳ — الگوی حرکتی و خط","plan":"الگوی حرکت پیش از فشار مداد؛ خط‌کشی، فاصله و اندازه با سه‌گانهٔ نوشتن.","criterion":"سه سطر پیاپی روی خط با فاصلهٔ پایدار.","items":[{"type":"exercise","text":"کارت بانک تمرین «پروتکل پیش‌نیاز نوشتن» (ستون بیست‌فایلی بانک) — فقط بخش هدف همین جلسه.","done":false,"linkId":null},{"type":"exercise","text":"نوشتن در هوا و ماسه — الگوی حرف هدف اول بزرگ در هوا، بعد در ماسه.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000104"},{"type":"exercise","text":"سه‌گانهٔ خط‌کشی نوشتن — خط‌کشی، فاصلهٔ جای انگشت و اندازهٔ حرف.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000204"},{"type":"homework","text":"گرم‌کردن روزانه با کارت بانک تمرین «هماهنگی دو نیمکره» پیش از نوشتن؛ دو دقیقه.","done":false,"linkId":null}]},{"title":"جلسهٔ ۴ — املا و دیکتهٔ هدفمند","plan":"اول بگو بعد بنویس؛ دیکتهٔ کوتاه از واژه‌های هدف جلسه‌های قبل و پروب پیگیری.","criterion":"کاهش خطای دیکته نسبت به مبنا در پروب پیگیری.","items":[{"type":"exercise","text":"اول بگو، بعد بنویس — جمله را بلند بگوید، بعد بنویسد.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000106"},{"type":"exercise","text":"کارت بانک تمرین «تمیز دیداری» — تفکیک دیداری حروف پیش از دیکته، پنج دقیقه.","done":false,"linkId":null},{"type":"probe","text":"پروب پیگیری — خطای دیکته و روانی نسبت به مبنا (ce-probe-write-v1).","done":false,"linkId":null},{"type":"homework","text":"دیکتهٔ سه‌واژه‌ای خانگی روی سطرکشی؛ کیفیت سه سطر، نه حجم.","done":false,"linkId":null}]},{"title":"جلسهٔ ۵ — جمع‌بندی دوره","plan":"پروب پایانی، مقایسهٔ روند و بستن برنامهٔ خانهٔ دو ماه بعد.","criterion":"معیار تسلط ۸۰٪ در دو جلسهٔ پیاپی یا تمدید دوره.","items":[{"type":"probe","text":"پروب پایانی — مقایسه با مبنا؛ معیار تسلط ۸۰٪ در دو جلسهٔ پیاپی (ce-probe-write-v1).","done":false,"linkId":null},{"type":"event","text":"فرم خانوادهٔ ce-sld-wri-v1 برای پیگیری دو هفته‌ای ارسال شود؛ در شک حرکت ظریف ارزیابی کاردرمانی نوبت‌بندی شود.","done":false,"linkId":null},{"type":"instruction","text":"نمونهٔ تاریخ‌دار ماهانه نگه داشته شود؛ در خانه کیفیت سنجیده شود نه حجم.","done":false,"linkId":null}]}]',
  1,
  1,
  'seed-m130'
);

-- ─── قالب 3 — فعال‌سازی توجه پایهٔ اول تا سوم (SNAP-IV دو مرجع + SDQ معلم در ۶ جلسه) ───
INSERT OR IGNORE INTO pathway_templates (id, key, title, description, protocol, target_key, steps, sessions_json, is_system, active, created_by) VALUES (
  'dddddddd-8200-4000-8000-000000000010',
  'sys-attention-g123',
  'فعال‌سازی توجه پایهٔ اول تا سوم — بستهٔ چندجلسه‌ای',
  'قالب سیستمی توجه برای سن مدرسه (پایهٔ اول تا سوم): شش جلسهٔ پیاپی از توجه پایدار به انتخابی و انتقالی با کاربرگ‌های واقعی بانک تمرین و بازی‌های قاعده‌دار، همراه خط پایهٔ SNAP-IV دو مرجع، پایش میان‌دوره‌ای معلم با SDQ و تمرین گذار در خانه. موتور بالینی برای هدف توجه پراپ ندارد — پایش این بسته با فرم‌های خانواده/معلم و دو سنجهٔ رفتاری انتخابی خانه/کلاس انجام می‌شود و این شکاف صراحتاً ثبت است. تشخیص نیست و ملاک دو-محیطی لازم است؛ قالب‌های ADHD 0128 مسیر تخصصی‌تری‌اند و این بسته فعال‌سازی روزمرهٔ کلاس-خانه است.',
  'mental_ot',
  'adhd',
  '[{"key":"assess","title":"خط پایهٔ دو مرجع","hint":"ce-snap-iv-p-v1 + ce-snap-iv-t-v1؛ ملاک دو-محیطی بدون هر دو فرم کامل نیست."},{"key":"sustained","title":"توجه پایدار","hint":"بستهٔ کاربرگ دقت و توجه پایدار بانک تمرین + بازه‌های کوتاه تایمردار."},{"key":"selective","title":"توجه انتخابی","hint":"کاربرگ توجه انتخابی + بازی پردازش دوکاناله + چراغ توجه برای بازداری پاسخ."},{"key":"classroom","title":"انتقال به کلاس","hint":"توجه انتقالی + پایش میان‌دوره‌ای معلم با ce-sdq-t-v1 و چک‌لیست تیک‌دار."},{"key":"monitor","title":"بازسنجی و تثبیت","hint":"بازپرسانی SNAP-IV دو مرجع پس از شش جلسه؛ مقایسه با مبنا و تصمیم تداوم."}]',
  '[{"title":"جلسهٔ ۱ — خط پایهٔ دو مرجع (۳۰ تا ۴۰ دقیقه)","plan":"ثبت SNAP-IV والد و معلم؛ انتخاب دو رفتار قابل شمارش برای شش جلسه.","criterion":"هر دو فرم در پرونده ثبت شده باشد.","items":[{"type":"event","text":"ثبت ce-snap-iv-p-v1 (فرم خانواده) به‌عنوان خط پایهٔ توجه.","done":false,"linkId":null},{"type":"event","text":"ارسال و پیگیری ce-snap-iv-t-v1 (فرم معلم) برای ملاک دو-محیطی.","done":false,"linkId":null},{"type":"instruction","text":"دو رفتار قابل شمارش کلاس/خانه انتخاب شود؛ همین دو تا پایان دوره سنجهٔ رفتاری بسته است.","done":false,"linkId":null}]},{"title":"جلسهٔ ۲ — توجه پایدار","plan":"کاربرگ دقت و توجه پایدار + بازهٔ کوتاه تایمردار؛ تکرار روزانهٔ کوتاه.","criterion":"اتمام یک برگ با خطای کم و یک بازهٔ ده‌دقیقه‌ای پیاپی.","items":[{"type":"exercise","text":"کارت بانک تمرین «افزایش دقت و توجه و حافظهٔ پایدار» (بستهٔ ده‌فایلی) — برگ جلسهٔ امروز.","done":false,"linkId":null},{"type":"exercise","text":"کارِ کوتاه با تایمر بصری — بازهٔ پنج تا ده دقیقه‌ای با وقفهٔ حرکتی کوتاه.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000110"},{"type":"homework","text":"روزی ده دقیقه کاربرگ + یک بازهٔ تایمردار؛ تیک‌ها در چک‌لیست خانه جمع شود.","done":false,"linkId":null}]},{"title":"جلسهٔ ۳ — توجه انتخابی","plan":"جدا کردن هدف از مزاحم: کاربرگ انتخابی و پردازش دوکاناله؛ بازی بازداری پاسخ.","criterion":"شکار هدف در برگ انتخابی با خطای کم؛ دو دور بازی با قاعدهٔ ثابت.","items":[{"type":"exercise","text":"کارت بانک تمرین «تقویت توجه انتخابی» — برگ جلسهٔ امروز.","done":false,"linkId":null},{"type":"game","text":"چراغ توجه: بازی سبز-قرمز خانه برای تمرین توقف و شروع.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000207"},{"type":"game","text":"کارت بانک تمرین «بازی دقت و پردازش دیداری و شنیداری» — پردازش دوکاناله، پنج تا هفت دقیقه.","done":false,"linkId":null},{"type":"homework","text":"تکرار بازی سبز-قرمز پیش از تکلیف، نه بعدش؛ روزی یک جلسهٔ کوتاه.","done":false,"linkId":null}]},{"title":"جلسهٔ ۴ — توجه انتقالی و پایش کلاس","plan":"جابه‌جایی بین دو مطلوب با قاعدهٔ دیداری؛ پایش میان‌دوره‌ای معلم.","criterion":"گذار بین دو فعالیت با یک یادآوری دیداری؛ فرم معلم ارسال و ثبت شود.","items":[{"type":"exercise","text":"کارت بانک تمرین «تقویت توجه انتقالی و پایدار» — برگ جلسهٔ امروز.","done":false,"linkId":null},{"type":"event","text":"پایش میان‌دوره‌ای: فرم معلم ce-sdq-t-v1 در میانهٔ دوره ارسال و ثبت شود.","done":false,"linkId":null},{"type":"exercise","text":"چک‌لیست تیک‌دار — کارهای روز روی برگهٔ دیداری؛ هر تیک بازخورد فوری.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000112"},{"type":"homework","text":"تمرین گذار در خانه: بین دو کار، دو دقیقه اخطار با تایمر بصری.","done":false,"linkId":null}]},{"title":"جلسهٔ ۵ — ماندگاری و دنبالهٔ دستور","plan":"ترکیب توجه و حافظهٔ کاری با سری کاربرگ توجه/تمرکز و دستور دومرحله‌ای؛ بازی نوبت‌گیری خانگی.","criterion":"اجرای دو دستور دومرحله‌ای از سه؛ پنج نوبت پیاپی در بازی.","items":[{"type":"exercise","text":"کارت بانک تمرین «سری کاربرگ‌های توجه، تمرکز و حافظهٔ فعال» (بستهٔ هشت‌فایلی) — سطح جلسهٔ امروز.","done":false,"linkId":null},{"type":"game","text":"دستور دومرحله‌ایِ بازی‌وار — فهم شنیداری و حافظهٔ کاری در قالب بازی.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000211"},{"type":"family","text":"بازی نوبت‌گیری هفتگی با خواهر/برادر؛ قاعدهٔ دیداری و سقف زمان کوتاه.","done":false,"linkId":null},{"type":"homework","text":"سطح بالاتر کاربرگ سری توجه در خانه؛ خطا با مدل‌دادن بررسی شود، نه نصیحت.","done":false,"linkId":null}]},{"title":"جلسهٔ ۶ — بازسنجی و تثبیت","plan":"بازپرسانی SNAP-IV دو مرجع و مقایسه با مبنا؛ تصمیم تداوم یا تعطیلی بسته.","criterion":"بازسنجی ثبت و مقایسه در پرونده باشد.","items":[{"type":"event","text":"بازپرسانی ce-snap-iv-p-v1 و مقایسه با مبنا؛ فرم معلم ce-snap-iv-t-v1 هم تکرار شود.","done":false,"linkId":null},{"type":"event","text":"گزارش SDQ معلمِ میانهٔ دوره کنار مبنا گذاشته شود و روند برای خانواده توضیح داده شود.","done":false,"linkId":null},{"type":"instruction","text":"در نبود پراپ توجه در موتور، روند با همین فرم‌ها و دو سنجهٔ رفتاری دوگانه سنجیده 