-- ─── قالب 4 — پیش‌مطلب ریاضی پایهٔ اول (پروتکل ریاضی بخش ۱ + شمارش برعکس در ۵ جلسه) ───
INSERT OR IGNORE INTO pathway_templates (id, key, title, description, protocol, target_key, steps, sessions_json, is_system, active, created_by) VALUES (
  'dddddddd-8200-4000-8000-000000000011',
  'sys-math-g1',
  'پیش‌مطلب ریاضی پایهٔ اول — بستهٔ چندجلسه‌ای',
  'قالب سیستمی پیش‌نیازهای ریاضی برای پایهٔ اول (در نوار پایهٔ اول تا سوم): پنج جلسهٔ پیاپی حس عدد ملموس، توالی و ترتیب عدد و حافظهٔ کاری عددی با پروتکل ریاضی و شمارش برعکس بانک تمرین، و پروب حساب به‌عنوان مبنا. پراپ ce-probe-calc-v1 واقعی موتور است اما ثبت آن در تولید هنوز آغاز نشده — خط پایه از اولین اجرا ساخته می‌شود و تا آن زمان مقایسهٔ روند معنا ندارد. این بسته پیش‌نیاز است، نه درمان نارساریاضی؛ در شک ماندگار به قالب اختلال یادگیری ریاضی برگردید.',
  'learning',
  'dyscalculia',
  '[{"key":"probe","title":"پروب پایهٔ حساب","hint":"ce-probe-calc-v1 — سلیقه و مقایسهٔ مقدار؛ اضطراب ریاضی هم ثبت شود."},{"key":"concrete","title":"حس عدد ملموس","hint":"مهرهٔ واقعی و کارت نقطه؛ دیدن و لمس پیش از نماد."},{"key":"sequence","title":"توالی و ترتیب عدد","hint":"پروتکل پیش‌نیاز ریاضی بانک تمرین + خط عدد زمینی با بدن."},{"key":"memory","title":"حافظهٔ کاری عددی","hint":"شمارش برعکس بانک تمرین از سه عدد؛ حساب ذهنی کوچک با پوشاندن مهره."},{"key":"applied","title":"موقعیت واقعی و پیگیری","hint":"بازی فروشگاه + پروب پیگیری؛ معیار تسلط ۸۰٪ در دو جلسهٔ پیاپی."}]',
  '[{"title":"جلسهٔ ۱ — پروب پایه و مرور ملاکی (۳۰ تا ۴۰ دقیقه)","plan":"اجرای پروب حساب و مرور چک‌لیست حساب؛ هدف کوچک و واقع‌بینانه برای پنج جلسه.","criterion":"ثبت مبنا در پروب مسیر.","items":[{"type":"probe","text":"اجرای ce-probe-calc-v1 — ثبت سلیقهٔ حساب و مقایسهٔ مقدار به‌عنوان مبنا.","done":false,"linkId":null},{"type":"event","text":"مرور نتیجهٔ ce-sld-calc-v1 و افتراق اضطراب ریاضی از حس عدد.","done":false,"linkId":null}]},{"title":"جلسهٔ ۲ — حس عدد ملموس","plan":"جمع و مقایسه با مهرهٔ واقعی؛ مقایسهٔ مقدار با دیدن، نه شمردن انگشتی.","criterion":"هفت مقایسهٔ درست از ده با کارت نقطه.","items":[{"type":"exercise","text":"شمارش با مهره‌های واقعی — جمع و کمتر/بیشتر را ببیند و لمس کند.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000107"},{"type":"exercise","text":"بازی مقایسهٔ مقدار با کارت‌های نقطه — دیدن یکجای مقدار کوچک.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000205"},{"type":"homework","text":"روزی هفت دقیقه مقایسهٔ تا ۵ در خانه؛ فشار و نمره ممنوع.","done":false,"linkId":null}]},{"title":"جلسهٔ ۳ — توالی و ترتیب عدد","plan":"بخش هدفمند پروتکل ریاضی بانک تمرین + ترتیب و فاصلهٔ عدد با بدن روی خط عدد.","criterion":"چیدن پنج عدد در ترتیب درست روی خط عدد.","items":[{"type":"exercise","text":"کارت بانک تمرین «پروتکل پیش‌نیازهای مهارت ریاضی (بخش ۱)» (کارت ده‌فایلی) — بخش جلسهٔ امروز.","done":false,"linkId":null},{"type":"exercise","text":"خط عدد روی زمین — پریدن روی خط عدد و فهم ترتیب و فاصله‌ها.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000109"},{"type":"homework","text":"ادامهٔ بخش کاربرگ پروتکل در خانه؛ هر کاربرگ بیشتر از ده دقیقه نکشد.","done":false,"linkId":null}]},{"title":"جلسهٔ ۴ — حافظهٔ کاری عددی","plan":"شمارش برعکس از سه عدد و حساب ذهنی کوچک با پوشاندن مهره.","criterion":"معکوس‌گویی درست چهار عدد در دو روز پیاپی.","items":[{"type":"exercise","text":"کارت بانک تمرین «شمارش برعکس» — از سه عدد شروع کنید و با موفقیت پله کنید.","done":false,"linkId":null},{"type":"exercise","text":"حساب ذهنی کوچک: مهره‌ها را بشمارد، بپوشانید و بپرسید چند تا بود؟","done":false,"linkId":null},{"type":"homework","text":"تکرار شمارش برعکس سه روز در هفته؛ موفقیت در جدول «توانستم» ثبت شود.","done":false,"linkId":null}]},{"title":"جلسهٔ ۵ — موقعیت واقعی و پروب پیگیری","plan":"بازی فروشگاه برای تعمیم حس عدد، پروب پیگیری و تصمیم دوره.","criterion":"حل یک موقعیت خرید با باقی‌پول ساده؛ مقایسهٔ پروب با مبنا.","items":[{"type":"exercise","text":"بازی فروشگاه — خرید و باقی‌پول با سکهٔ اسباب‌بازی.","done":false,"linkId":"cccccccc-8200-4000-8000-000000000108"},{"type":"probe","text":"پروب پیگیری — مقایسه با مبنا؛ معیار تسلط ۸۰٪ در دو جلسهٔ پیاپی (ce-probe-calc-v1).","done":false,"linkId":null},{"type":"instruction","text":"در خانه از مهره و خط عدد شروع کنید، نه جدول ضرب؛ در شک ماندگار به قالب اختلال یادگیری ریاضی برگردید.","done":false,"linkId":null}]}]',
